@testset "GF(256) exhaustive operands" begin
    independent(a,b) = begin
        p = 0
        for shift in 0:7
            (b >> shift) & 1 == 1 && (p ⊻= a << shift)
        end
        for shift in 14:-1:8
            (p >> shift) & 1 == 1 && (p ⊻= 0x11d << (shift - 8))
        end
        p
    end
    for a in 0:255, b in 0:255
        @test QR.gf_multiply(a,b) == independent(a,b)
    end
    for v in (true,false,-1,256,1.0,"1",nothing)
        @test_throws QR.InvalidInputError QR.gf_multiply(v,1)
        @test_throws QR.InvalidInputError QR.gf_multiply(1,v)
    end
end

@testset "Reed-Solomon every supported degree" begin
    data = UInt8[mod(i*93+11,256) for i in 0:256]
    for degree in 1:255
        divisor = QR.reed_solomon_divisor(degree)
        @test _core_sha(divisor) == _RS_REFERENCES[degree][1]
        @test _core_sha(QR.reed_solomon_remainder(data,degree)) == _RS_REFERENCES[degree][2]
        divisor[1] = 0
        @test QR.reed_solomon_divisor(degree)[1] == 1
    end
    for d in (0,256,true,1.0,nothing)
        @test_throws QR.InvalidInputError QR.reed_solomon_divisor(d)
    end
    for bytes in ([-1],[256],[true],"abc",fill(0,3707))
        @test_throws QR.InvalidInputError QR.reed_solomon_remainder(bytes,7)
    end
end

@testset "Every version, ECC and mask" begin
    @test QR.alignment_positions(1) == ()
    @test QR.alignment_positions(2) == (6,18)
    @test QR.alignment_positions(32) == (6,34,60,86,112,138)
    @test QR.alignment_positions(40) == (6,30,58,86,114,142,170)
    for (version,level,inter_hash,hashes,penalties) in _CORE_REFERENCES
        li = findfirst(==(level),QR.ERROR_CORRECTION_LEVEL_ORDER)-1
        data = UInt8[mod(i*149+version*7+li*31,256) for i in 0:(QR.data_codeword_count(version,level)-1)]
        inter = QR.interleave_codewords(data,version,level)
        @test _core_sha(inter.codewords) == inter_hash
        @test inter.data_codewords == length(data)
        @test inter.total_codewords == QR.raw_codeword_count(version)
        @test inter.error_correction_codewords + inter.data_codewords == inter.total_codewords
        for mask in 0:7
            result = QR.build_matrix(inter.codewords,version,level,mask)
            @test result.matrix isa Matrix{Bool}
            @test size(result.matrix) == (QR.qr_size(version),QR.qr_size(version))
            @test _matrix_sha(result.matrix) == hashes[mask+1]
            @test result.penalty == penalties[mask+1]
            @test QR.penalty_score(result.matrix) == result.penalty
            @test result.mask_pattern == mask
            @test result.mask_penalties == ((mask_pattern=mask,penalty=penalties[mask+1]),)
        end
        auto = QR.build_matrix(inter.codewords,version,level)
        best = argmin(penalties)-1
        @test auto.mask_pattern == best
        @test auto.penalty == penalties[best+1]
        @test _matrix_sha(auto.matrix) == hashes[best+1]
        @test Tuple(p.penalty for p in auto.mask_penalties) == penalties
        @test QR.build_matrix(inter.codewords,version,level;mask_pattern=0).matrix == QR.build_matrix(inter.codewords,version,level,0).matrix
    end
    for version in (0,41,true,1.0,"1",nothing)
        @test_throws QR.InvalidVersionError QR.qr_size(version)
        @test_throws QR.InvalidVersionError QR.block_info(version,"M")
    end
    for level in ("m","X",:M,nothing,1)
        @test_throws QR.InvalidEccError QR.data_codeword_count(1,level)
    end
    for mask in (-1,8,true,1.0,"0")
        @test_throws QR.InvalidInputError QR.build_matrix(zeros(UInt8,26),1,"M",mask)
    end
    @test_throws QR.InvalidInputError QR.build_matrix(zeros(UInt8,26),1,"M",0;mask_pattern=0)
    @test_throws QR.InvalidInputError QR.build_matrix(zeros(UInt8,25),1,"M")
    @test_throws QR.InvalidInputError QR.interleave_codewords(zeros(UInt8,15),1,"M")
    for matrix in (zeros(Int,3,3),fill(true,3,4),fill(true,0,0),fill(true,178,178),[[true]])
        @test_throws QR.InvalidInputError QR.penalty_score(matrix)
    end
end

@testset "Segments and strict boundary validation" begin
    for (segment,version,hash) in _SEGMENT_REFERENCES
        encoded = QR.bits(segment,version)
        @test _core_sha(UInt8.(encoded)) == hash
        @test length(encoded) == QR.bit_length(segment,version)
    end
    @test QR.kanji_value('漢') == 1855
    @test QR.can_encode_kanji("漢")
    @test !QR.can_encode_kanji("漢字")
    @test !QR.can_encode_kanji('😂')
    @test !QR.can_encode_kanji('a')
    @test length(QR._KANJI_KEYS) == 6953
    pinned = UInt8[]
    for i in eachindex(QR._KANJI_KEYS)
        k,c = QR._KANJI_KEYS[i],QR._KANJI_CODES[i]
        append!(pinned,UInt8[(k>>8)&255,k&255,(c>>8)&255,c&255])
        @test QR.can_encode_kanji(Char(k))
        adjusted = Int(c)-(c <= 0x9ffc ? 0x8140 : 0xc140)
        @test QR.kanji_value(Char(k)) == (adjusted>>8)*192+(adjusted&255)
    end
    @test _core_sha(pinned) == "be0a434df7babc88848f0930ceb3ea9424c6715d89ed4b1b19bcb416f9892fa8"
    s = QR.byte("Aé漢😂\0")
    @test s.count == 11
    @test s.character_count == 5
    @test s.byte_count == 11
    @test s.text == "Aé漢😂\0"
    @test QR.kanji("漢字").byte_count == 4
    @test QR.kanji("漢字").logical_bytes == collect(codeunits("漢字"))
    source = UInt8[0,255,128]
    binary = QR.byte(source)
    source[1] = 99
    @test binary.data == UInt8[0,255,128]
    returned = binary.data; returned[1] = 99
    returned2 = binary.logical_bytes; returned2[1] = 99
    @test binary.data == UInt8[0,255,128]
    @test binary.character_count == 0
    @test binary.text === nothing
    @test QR.bits(binary,1)[13:20] == zeros(Int,8)
    for data in ([true],[-1],[256],[1.0],nothing,1)
        @test_throws QR.InvalidInputError QR.byte(data)
    end
    malformed = ([0x80],[0xc0,0x80],[0xe0,0x80,0x80],[0xed,0xa0,0x80],
        [0xf4,0x90,0x80,0x80],[0xf0,0x80,0x80,0x80],[0xe2,0x82],[0xc2,0x7f])
    for raw in malformed
        @test_throws QR.InvalidInputError QR.byte(String(UInt8.(raw)))
        @test QR.byte(UInt8.(raw)).data == raw
    end
    for mode in (nothing,1,"auto","unknown",true)
        @test_throws QR.InvalidModeError QR.Segment(mode,"data")
    end
    @test_throws QR.InvalidModeError QR.numeric("１２")
    @test_throws QR.InvalidModeError QR.alphanumeric("lower")
    @test_throws QR.InvalidModeError QR.kanji("😂")
    for value in (true,-1,1000000,1.0,"26",nothing)
        @test_throws QR.InvalidEciError QR.eci(value)
    end
    for value in ("1","123","Ä","é","!",1,nothing)
        @test_throws QR.InvalidModeError QR.fnc1_second(value)
    end
    @test QR.fnc1_second("99").application_indicator_codeword == 99
    @test QR.fnc1_second("z").application_indicator_codeword == 222
    @test_throws QR.InvalidModeError QR.structured_append_segment(1,1,0)
    @test_throws QR.InvalidModeError QR.structured_append_segment(3,2,0)
    @test_throws QR.InvalidModeError QR.structured_append_segment(true,2,0)
    @test_throws QR.InvalidModeError QR.structured_append_segment(1,2,256)
    @test_throws QR.InvalidGs1Error QR.Segment("fnc1","data")
    @test_throws QR.InvalidModeError QR.Segment("byte","data";index=1)
    @test_throws QR.InvalidInputError QR.Segment("byte","data";ignored=1)
    manual = QR.normalize_segments([(mode="fnc1",),(mode="alphanumeric",text="A%%B%C")])
    @test manual[2].data == "A%%B%C"
    @test QR.normalize_segments([(mode="eci",assignment_number=26),(mode="eci",assignment_number=27),(mode="byte",bytes=[255])])[3].data == [255]
    @test_throws QR.InvalidGs1Error QR.normalize_segments([QR.byte("x"),QR.fnc1()])
    @test_throws QR.InvalidGs1Error QR.normalize_segments([QR.fnc1(),QR.eci(26)])
    @test_throws QR.InvalidModeError QR.normalize_segments([QR.fnc1_second("A"),QR.eci(26)])
    @test_throws QR.InvalidGs1Error QR.normalize_segments([(mode="fnc1",data=nothing)])
    @test_throws QR.InvalidInputError QR.normalize_segments([(mode="byte",data="x",text="x")])
    @test_throws QR.InvalidInputError QR.normalize_segments([(mode="byte",data="x",ignored=1)])
    @test_throws QR.InvalidInputError QR.normalize_segments([Dict("mode"=>"byte",:mode=>"byte")])
    @test_throws QR.InvalidModeError QR.normalize_segments([(data="x",)])
    @test_throws QR.InvalidInputError QR.normalize_segments("text")
    @test_throws QR.InvalidInputError QR.normalize_segments([1])
    @test_throws QR.DataTooLongError QR.byte(zeros(UInt8,1_000_001))
    @test_throws QR.DataTooLongError QR.byte(repeat("a",1_000_001))
    @test_throws QR.DataTooLongError QR.normalize_segments(fill(QR.byte(""),16_385))
    @test_throws QR.DataTooLongError QR.normalize_segments([QR.byte(repeat("a",600_000)),QR.byte(repeat("b",400_001))])
    @test QR.bit_length(QR.byte(repeat("a",256)),1) == 2060
    @test_throws QR.DataTooLongError QR.bits(QR.byte(repeat("a",256)),1)
    @test_throws QR.DataTooLongError QR.bits(QR.numeric(repeat("1",7090)),40)
    @test_throws QR.DataTooLongError QR.segments_bits([QR.byte(repeat("a",1600)),QR.byte(repeat("a",1600))],40)
    @test_throws QR.InvalidInputError QR.pad_data_bits([true],1,"M")
    @test_throws QR.InvalidInputError QR.pad_data_bits([2],1,"M")
    @test_throws QR.DataTooLongError QR.pad_data_bits(zeros(Int,129),1,"M")
    @test QR.pad_data_bits(Int[],1,"M") == UInt8[0; [isodd(i) ? 0xec : 0x11 for i in 1:15]]
    @test QR.pad_data_bits(ones(Int,128),1,"M") == fill(0xff,16)
end

@testset "Independent concurrent calls" begin
    jobs = [Threads.@spawn begin
        s = QR.byte("Concurrent 漢字 😂 $i")
        d = QR.pad_data_bits(QR.bits(s,4),4,"Q")
        cw = QR.interleave_codewords(d,4,"Q")
        m = QR.build_matrix(cw.codewords,4,"Q")
        (m,QR.build_matrix(cw.codewords,4,"Q"))
    end for i in 1:16]
    for job in jobs
        a,b = fetch(job)
        @test a.matrix == b.matrix
        a.matrix[1,1] = !a.matrix[1,1]
        @test a.matrix != b.matrix
    end
end

@testset "Low-level aggregate payload bound" begin
    large = QR.Segment("numeric", repeat("1",600001))
    @test_throws QR.DataTooLongError QR.segments_bit_length([large,large],40)
end
